static void sanitize(char *dst, size_t n, const char *dll) {
    size_t j = 0;
    for (size_t i = 0; dll[i] && j + 1 < n; i++) {
        unsigned char c = (unsigned char)dll[i];
        if (c == '/' || c == '\\') { j = 0; continue; }
        dst[j++] = runtime.isalnum(c) ? (char)c : '_';
    }
    dst[j] = 0;
    if (!j) runtime.snprintf(dst, n, "dll");
}
static void ar_append_member(Buffer *file, const char *name, const Buffer *payload) {
    char hdr[60];
    runtime.memset(hdr, ' ', 60);
    size_t nl = runtime.strlen(name);
    if (nl > 16) nl = 16;
    runtime.memcpy(hdr, name, nl);
    runtime.memcpy(hdr + 16, "0           ", 12);
    runtime.memcpy(hdr + 28, "0     ", 6);
    runtime.memcpy(hdr + 34, "0     ", 6);
    runtime.memcpy(hdr + 40, "0       ", 8);
    char sz[16];
    runtime.snprintf(sz, sizeof sz, "%-10u", (unsigned)payload->len);
    runtime.memcpy(hdr + 48, sz, 10);
    hdr[58] = '`';
    hdr[59] = '\n';
    buffer_append(file, hdr, 60);
    buffer_append(file, payload->data, payload->len);
    if (payload->len & 1) {
        char pad = '\n';
        buffer_append(file, &pad, 1);
    }
}
static char *basename_dll(const char *path) {
    const char *base = path ? path : "out.dll";
    for (const char *p = base; *p; p++)
        if (*p == '/' || *p == '\\') base = p + 1;
    size_t n = runtime.strlen(base);
    if (n > 4 && icmp(base + n - 4, ".dll") == 0)
        n -= 4;
    const char *stem = base;
    size_t sn = n;
    if (sn > 3 && runtime.strncmp(stem, "lib", 3) == 0) {
        stem += 3;
        sn -= 3;
    }
    char *s = runtime.malloc(sn + 1);
    if (!s) { runtime.fprintf(runtime.stderr, "fakecc: OOM\n"); runtime.exit(1); }
    runtime.memcpy(s, stem, sn);
    s[sn] = 0;
    return s;
}
static char *parent_dir(const char *path) {
    const char *slash = ((void*)0);
    for (const char *p = path; p && *p; p++)
        if (*p == '/' || *p == '\\') slash = p;
    if (!slash) return xstrdup(".");
    size_t n = (size_t)(slash - path);
    if (!n) return xstrdup("\\");
    char *d = runtime.malloc(n + 1);
    if (!d) { runtime.fprintf(runtime.stderr, "fakecc: OOM\n"); runtime.exit(1); }
    runtime.memcpy(d, path, n);
    d[n] = 0;
    return d;
}
